draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-75, 100, 10);
  ctx.fillRect(W/2-25, H/2-50, 50, 100);

  // stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-150, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-130);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2-30, H/2-70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2+30, H/2-70);
  ctx.stroke();

  // applying wisdom
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply', W/2, H/2+50 + 20*Math.sin(t));

  // lesson life
  ctx.font = '18px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson', W/2-50, H/2+100 + 10*Math.cos(t));
  ctx.fillText('Life', W/2-50, H/2+120 + 10*Math.cos(t+Math.PI/2));

  // numbers
  ctx.font = '36px Arial';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'bottom';
  ctx.fillStyle = 'black';
  ctx.fillText('752', W-20, H-20 + 10*Math.sin(t));

  ctx.restore();
}
